subroutine ESSD_design_points ( order, n, x )
    ! Equivalent for the ESD of the subroutine design_points in sphere_design_rule.f90  
    implicit none

    integer ( kind = 4 ) n
    integer ( kind = 4 ) order
    real ( kind = 8 ) x(n)

    if ( order == 1 ) then
        call ESSD_001_00002 ( x )
    elseif ( order == 3 ) then
        call ESSD_003_00006 ( x )
    elseif ( order == 5 ) then
        call ESSD_005_00012 ( x )
    elseif ( order == 7 ) then
        call ESSD_007_00032 ( x )
    elseif ( order == 9 ) then
        call ESSD_009_00048 ( x )
    elseif ( order == 11 ) then
        call ESSD_011_00070 ( x )
    elseif ( order == 13 ) then
        call ESSD_013_00094 ( x )
    elseif ( order == 15 ) then
        call ESSD_015_00120 ( x )
    elseif ( order == 17 ) then
        call ESSD_017_00156 ( x )
    elseif ( order == 19 ) then
        call ESSD_019_00192 ( x )
    elseif ( order == 21 ) then
        call ESSD_021_00234 ( x )
    elseif ( order == 23 ) then
        call ESSD_023_00278 ( x )
    elseif ( order == 25 ) then
        call ESSD_025_00328 ( x )
    elseif ( order == 27 ) then
        call ESSD_027_00380 ( x )
    elseif ( order == 29 ) then
        call ESSD_029_00438 ( x )
    elseif ( order == 31 ) then
        call ESSD_031_00498 ( x )
    elseif ( order == 33 ) then
        call ESSD_033_00564 ( x )
    elseif ( order == 35 ) then
        call ESSD_035_00632 ( x )
    elseif ( order == 37 ) then
        call ESSD_037_00706 ( x )
    elseif ( order == 39 ) then
        call ESSD_039_00782 ( x )
    elseif ( order == 41 ) then
        call ESSD_041_00864 ( x )
    elseif ( order == 43 ) then
        call ESSD_043_00948 ( x )
    else
        write ( *, '(a)' ) ' '
        write ( *, '(a)' ) 'EFFICIENT SPHERICAL T DESIGN_POINTS - Fatal error!'
        write ( *, '(a,i6)' ) '  There is no information for ORDER = ', order
        stop
    end if

    return
end
subroutine ESSD_design_closer_order ( n, order, ndes )
! Equivalent for the ESSD of the subroutine design_closer_order in sphere_design_rule.f90

    implicit none

    integer ( kind = 4 ) n,ndes,dmin
    integer ( kind = 4 ) order,pos_order
    integer ( kind = 4 ),dimension(22) :: all_avail_n
    integer ( kind = 4 ),dimension(22) :: d

    all_avail_n = [2,6,12,32,48,70,94,120,156,192,234,278,328,380,438,498,564,632,706,782,864,948]; ! note that I can do more (up to 52978)
                    
    d = all_avail_n - n;
    pos_order = minloc(d,1,mask=(d .ge. 0));
    order = 2*pos_order-1;
    ndes = all_avail_n(pos_order);

    return
end    